insert into public.software (name, slug, tagline, description_short, description_full, logo_url, category_id, starting_price, price_currency, billing_period, price_is_net, price_unit, free_trial, trial_days, free_version, free_demo, pricing_plans, pricing_note, features, top_features, integrations, pros, cons, ideal_for, brand_color, gobd_compliant, datev_interface, e_invoicing, elster_submission, hosting_location, dpa_available, iso27001, tse_certified, skr_support, german_support, vendor_country, compliance_checked_at, affiliate_url, vendor_website, affiliate_network, vendor_name, founded_year, vendor_hq, support_types, countries_available, languages, editorial_rating, editorial_ease, editorial_value, editorial_service, editorial_functionality, editorial_verdict, editorial_review, editorial_author, editorial_tested_at, status, featured) values
('easybill', 'easybill', 'Rechnungsprogramm mit starken E-Commerce-Anbindungen', 'Online-Rechnungsprogramm mit Schnittstellen zu Amazon, eBay, Shopify und Co., GoBD-konform mit DATEV-Export.', '<p>easybill ist ein Online-Rechnungsprogramm, das besonders im E-Commerce verbreitet ist. Bestellungen aus Marktplätzen und Shops werden automatisch in Rechnungen umgewandelt, inklusive korrekter Umsatzsteuer für EU-Lieferungen (OSS).</p><p>Die Rechnungsdaten lassen sich per DATEV-Export an die Steuerkanzlei übergeben. E-Rechnungen werden im Format XRechnung und ZUGFeRD erstellt.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 0, 'EUR', 'month', true, 'account', true, 7, true, false, '[{"name":"Free","price":0,"period":"month","unit":"account","features":["50 Dokumente im Monat inkl. E-Rechnung","1 Nutzer"]},{"name":"Starter","price":12,"period":"month","unit":"account","features":["250 Dokumente im Monat","KI-Belegerfassung","Eigenes Briefpapier"]},{"name":"Professional","price":39,"period":"month","unit":"account","features":["Unbegrenzte Kunden","Wiederkehrende Rechnungen","Versand über DHL, DPD, Hermes, GLS","Marktplatz-Anbindungen"],"highlighted":true},{"name":"Premium","price":45,"period":"month","unit":"account","features":["Automatisches Mahnwesen","Projekte und Zeiterfassung","Automatisierung per API"]}]'::jsonb, 'bei monatlicher Zahlung; jährlich ab 9 €', '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","DATEV-Export","Mahnwesen","SEPA-Lastschrift"]'::jsonb, '["Marktplatz- und Shop-Anbindungen","OSS-Umsatzsteuer für EU-Verkäufe","Automatischer Rechnungsversand"]'::jsonb, '["Amazon","eBay","Shopify","WooCommerce","Shopware","DATEV","PayPal"]'::jsonb, '["Sehr gute Shop-Integrationen","Automatisierung hoher Rechnungsvolumen"]'::jsonb, '["Keine vollständige Finanzbuchhaltung","Viele Funktionen erst in höheren Tarifen"]'::jsonb, 'Online-Händler mit hohem Rechnungsvolumen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, false, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.easybill.de/', 'keins', 'easybill GmbH', null, 'Sulingen', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.2, 4.3, 4.1, 4.1, 4.2, 'easybill ist ein spezialisiertes Rechnungsprogramm, das besonders im Onlinehandel glänzt. Marktplatzanbindung, Versand und wiederkehrende Rechnungen machen es zur ersten Wahl für Händler, die ihre Buchhaltung der Kanzlei überlassen.', '<h3>Worauf easybill spezialisiert ist</h3><p>easybill schreibt Rechnungen, und zwar sehr viele davon. Die Software verbindet sich mit Marktplätzen und Shops, erzeugt aus Bestellungen automatisch Rechnungen und Lieferscheine und kann Versandlabels für DHL, DPD, Hermes und GLS drucken. Die Daten gehen im DATEV-Format an die Kanzlei.</p><h3>Tarife</h3><p>Die kostenlose Version erlaubt 50 Dokumente im Monat inklusive E-Rechnung. Starter für 12 € bringt 250 Dokumente, eine KI-Belegerfassung und eigenes Briefpapier. Professional für 39 € ist der Tarif für Händler: unbegrenzte Kunden, wiederkehrende Rechnungen, Versandabwicklung und Marktplatz-Anbindungen. Premium für 45 € ergänzt automatisches Mahnwesen, Projekte und Zeiterfassung.</p><p>Bei jährlicher Zahlung kosten die Tarife 9 €, 25 € und 37 €. Die Server stehen in Deutschland, und die Einrichtung übernimmt easybill kostenlos.</p><h3>Einschränkungen</h3><p>easybill ersetzt keine Buchhaltung. Wer EÜR und Umsatzsteuer selbst erledigen möchte, braucht ein zweites Programm oder die Kanzlei. Die Testphase ist mit sieben Tagen recht kurz, gilt aber für alle Funktionen und ohne Kreditkarte.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Scopevisio', 'scopevisio', 'Cloud-Unternehmenssoftware mit Finanzbuchhaltung für den Mittelstand', 'Cloud-ERP aus Bonn mit Finanzbuchhaltung, Dokumentenmanagement und CRM für mittelständische Unternehmen.', '<p>Scopevisio bietet eine Cloud-Unternehmenssoftware mit Finanzbuchhaltung, Kostenrechnung, Dokumentenmanagement und CRM. Die Plattform richtet sich an mittelständische Unternehmen und Steuerberater, die Prozesse vollständig in der Cloud abbilden möchten.</p><p>Die Daten werden in Deutschland gehostet; die Finanzbuchhaltung unterstützt Bilanzierung nach HGB und die Übergabe an DATEV.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), null, 'EUR', 'month', true, 'user', true, 30, false, true, '[]'::jsonb, 'modular nach Plattform, Modulen und Nutzern', '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","Belegerfassung per OCR","Bankanbindung","UStVA per ELSTER","Bilanz & GuV","DATEV-Export","Mahnwesen","Anlagenverwaltung","SEPA-Lastschrift"]'::jsonb, '["FiBu, DMS und CRM in einer Cloud","Kostenrechnung","Hosting in Deutschland"]'::jsonb, '["DATEV","Microsoft 365","Outlook"]'::jsonb, '["Breiter Funktionsumfang","Deutsches Hosting"]'::jsonb, '["Einführung braucht Projektaufwand","Preis nur auf Anfrage"]'::jsonb, 'Mittelständler, die Finanzen und Dokumente zentral in der Cloud führen wollen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, true, 'Deutschland', true, null, null, '["SKR03","SKR04"]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.scopevisio.com', 'keins', 'Scopevisio AG', null, 'Bonn', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.1, 3.8, 3.9, 4.2, 4.6, 'Scopevisio ist eine Cloud-Unternehmenssoftware aus Bonn, die weit über die Buchhaltung hinausgeht. Für wachsende Mittelständler mit mehreren Gesellschaften ist sie eine ernsthafte Alternative zu klassischen ERP-Systemen.', '<h3>Einordnung</h3><p>Wer Scopevisio in einer Reihe mit Lexware Office oder sevdesk sieht, unterschätzt das Programm. Finanzbuchhaltung, Kostenrechnung, Vertrieb, Einkauf, Dokumentenmanagement und Personal lassen sich modular kombinieren. Das Ergebnis ist eher ein Cloud-ERP mit sehr starker Finanzbuchhaltung.</p><h3>Stärken</h3><p>Mandantenfähigkeit und Konsolidierung sind ausgereift, ebenso die Zusammenarbeit mit Steuerberatung und Wirtschaftsprüfung. Die Daten liegen in deutschen Rechenzentren, was für viele Mittelständler ein wichtiges Argument ist.</p><h3>Preismodell</h3><p>Feste Tarife gibt es nicht. Der Preis setzt sich aus Plattform, gebuchten Modulen und benannten Nutzern zusammen. Die Beispielrechnungen des Anbieters liegen bei etwa 1,70 € bis 2,40 € pro Nutzer und Tag. Für ein konkretes Angebot führt kein Weg an einem Gespräch vorbei. Eine Testphase von 30 Tagen endet automatisch.</p><h3>Für wen es passt</h3><p>Für Kleinstbetriebe ist Scopevisio überdimensioniert. Ab etwa 20 Mitarbeitenden, mehreren Gesellschaften oder dem Wunsch nach einer durchgängigen Cloud-Lösung lohnt der Blick.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Pennylane', 'pennylane', 'Finanzplattform für Unternehmen und Steuerkanzleien', 'Kanzlei-zentrierte Finanzplattform mit Belegmanagement, Zahlungsverkehr und DATEV-Anbindung.', '<p>Pennylane ist eine Finanz- und Buchhaltungsplattform, die Unternehmen und Steuerkanzleien in einer gemeinsamen Oberfläche zusammenbringt. Belege, Rechnungen und Zahlungen werden zentral erfasst und stehen der Kanzlei unmittelbar zur Verfügung.</p><p>Für den deutschen Markt bietet Pennylane eine DATEV-Anbindung; das Hosting erfolgt in der EU.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), null, 'EUR', 'month', true, 'client', false, null, false, true, '[]'::jsonb, null, '["Rechnungen & Angebote","E-Rechnung (XRechnung/ZUGFeRD)","Belegerfassung per OCR","Bankanbindung","DATEV-Export","Mahnwesen"]'::jsonb, '["Gemeinsame Oberfläche mit der Kanzlei","Zahlungsverkehr integriert","DATEV-Anbindung"]'::jsonb, '["DATEV","Qonto","Stripe","Shopify"]'::jsonb, '["Modernes Interface","Stark in der Kanzlei-Zusammenarbeit"]'::jsonb, '["In Deutschland noch jung","Preis nur auf Anfrage"]'::jsonb, 'Wachsende Unternehmen mit moderner Kanzlei.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'EU', true, null, null, '[]'::jsonb, true, 'Frankreich', '2026-09-22', null, 'https://www.pennylane.com/de', 'keins', 'Pennylane', 2020, 'Paris (DE-Niederlassung Berlin)', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4, 4.3, 3.9, 3.9, 4, 'Pennylane ist eine moderne Finanzplattform aus Frankreich, die Unternehmen und Kanzleien auf einer gemeinsamen Oberfläche zusammenbringt. In Deutschland ist sie noch jung, die Grundidee aber überzeugt.', '<h3>Die Idee</h3><p>Pennylane will die Trennung zwischen Unternehmenssoftware und Kanzleisoftware aufheben. Beide Seiten arbeiten im selben System: Das Unternehmen erfasst Belege, bezahlt Rechnungen und sieht seine Zahlen in Echtzeit, die Kanzlei bucht und schließt ab, ohne dass Daten exportiert werden.</p><h3>Stärken</h3><p>Die Oberfläche ist schnell und klar, die Auswertungen für Liquidität und Kosten sind ein echter Mehrwert für Geschäftsführungen. In Frankreich nutzen viele Kanzleien die Plattform bereits als Standard.</p><h3>Was Sie bedenken sollten</h3><p>Der deutsche Markt wird noch aufgebaut. Fragen Sie vor der Entscheidung, ob Ihre Kanzlei mit Pennylane arbeitet oder zumindest einen reibungslosen Export ins eigene System erhält. Preise veröffentlicht Pennylane für Deutschland derzeit nicht, eine Demo ist kostenlos.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Candis', 'candis', 'Rechnungsfreigabe und Kreditorenbuchhaltung automatisieren', 'Eingangsrechnungen erfassen, freigeben und per DATEV-Export an die Buchhaltung übergeben.', '<p>Candis automatisiert die Kreditorenbuchhaltung: Eingangsrechnungen werden per E-Mail oder Upload erfasst, ausgelesen, über konfigurierbare Freigabe-Workflows geprüft und vorkontiert.</p><p>Die Übergabe an die Buchhaltung erfolgt per DATEV-Schnittstelle. Candis eignet sich besonders für Unternehmen mit vielen Eingangsrechnungen und mehrstufigen Freigaben.</p>', null, (select id from public.categories where slug = 'buchhaltungssoftware'), 389, 'EUR', 'month', true, 'account', true, 30, false, true, '[{"name":"Basis","price":389,"period":"month","unit":"account","features":["Unbegrenzt Nutzer und Gesellschaften","Implementierung und Onboarding inklusive"]},{"name":"Plus","price":599,"period":"month","unit":"account","features":["Erweiterte Freigabe-Workflows"],"highlighted":true},{"name":"Max","price":789,"period":"month","unit":"account","features":["Voller Funktionsumfang"]}]'::jsonb, 'Preis richtet sich nach dem Belegvolumen', '["Belegerfassung per OCR","E-Rechnung (XRechnung/ZUGFeRD)","DATEV-Export","SEPA-Lastschrift","Mobile App"]'::jsonb, '["Mehrstufige Freigabe-Workflows","Vorkontierung","DATEV-Übergabe"]'::jsonb, '["DATEV","Microsoft 365","Slack"]'::jsonb, '["Spart viel Zeit bei Eingangsrechnungen","Klare Freigabeprozesse"]'::jsonb, '["Kein Ausgangsrechnungswesen","Einstieg erst ab 389 € im Monat"]'::jsonb, 'Mittelständler mit vielen Eingangsrechnungen.', null, 'ja', 'export', '["XRechnung","ZUGFeRD"]'::jsonb, null, 'Deutschland', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.candis.io', 'keins', 'Candis GmbH', 2015, 'Berlin', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch","Englisch"]'::jsonb, 4.3, 4.3, 3.8, 4.4, 4.4, 'Candis digitalisiert die Eingangsrechnungen mittelständischer Unternehmen von der Erfassung bis zur Zahlung. Mit einem Einstieg ab 389 € im Monat richtet es sich klar an Firmen, bei denen dieser Prozess heute viele Stunden kostet.', '<h3>Wofür Candis gebaut ist</h3><p>Candis ist keine Buchhaltung, sondern ein Werkzeug für den Kreditorenprozess. Rechnungen kommen per E-Mail oder Upload an, werden ausgelesen, von den zuständigen Personen freigegeben, kontiert und zur Zahlung vorbereitet. Am Ende gehen die Buchungen mit Beleg an DATEV.</p><h3>Stärken</h3><p>Die Freigabe-Workflows sind flexibel und bilden auch mehrstufige Genehmigungen ab. Kostenstellen, Projekte und Budgets lassen sich direkt bei der Freigabe zuordnen. Die Anbindung an DATEV ist eng, was die Kanzlei spürbar entlastet.</p><h3>Kosten</h3><p>Basis beginnt bei 389 € im Monat, Plus bei 599 € und Max bei 789 €. Der genaue Preis richtet sich nach dem Belegvolumen. Enthalten sind unbegrenzt viele Nutzer und Gesellschaften sowie Implementierung, Onboarding und Support. Eine 30-tägige Testphase ist kostenlos.</p><h3>Unser Fazit</h3><p>Für Unternehmen mit mehreren hundert Eingangsrechnungen im Monat und verteilten Freigaben ist Candis eine der besten Lösungen am Markt. Für kleinere Betriebe übersteigen die Kosten den Nutzen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('DATEV Lohn und Gehalt', 'datev-lohn-und-gehalt', 'Der Marktstandard für die Lohnabrechnung in Kanzlei und Unternehmen', 'Lohn- und Gehaltsabrechnung mit ELStAM, DEÜV-Meldungen und Beitragsnachweisen, meist über die Steuerkanzlei.', '<p>DATEV Lohn und Gehalt ist das verbreitetste Programm für die Entgeltabrechnung in Deutschland. Es bildet Lohnsteuer, Sozialversicherung, Meldewesen und Bescheinigungen vollständig ab und wird laufend an gesetzliche Änderungen angepasst.</p><p>Die meisten Unternehmen nutzen es über ihre Steuerkanzlei; größere Unternehmen setzen es auch im eigenen Haus ein.</p>', null, (select id from public.categories where slug = 'lohnabrechnung'), null, 'EUR', 'month', true, 'employee', false, null, false, true, '[]'::jsonb, 'Lizenz über die Steuerkanzlei', '["Entgeltabrechnung","ELStAM-Abruf","Lohnsteueranmeldung","DEÜV-Meldungen","Beitragsnachweise","Lohnsteuerbescheinigung","bAV & Entgeltumwandlung","Umlagen U1/U2/U3","Mitarbeiterportal","DATEV-Schnittstelle","Baulohn"]'::jsonb, '["Vollständiges Meldewesen","Laufende Gesetzesaktualisierung","Baulohn und Sonderfälle"]'::jsonb, '["DATEV Unternehmen online","Personio","HRworks","clockodo"]'::jsonb, '["Rechtssicher und vollständig","Kanzleien kennen es"]'::jsonb, '["Komplexe Oberfläche","Kaum Self-Service ohne Kanzlei"]'::jsonb, 'Unternehmen, deren Lohn die Kanzlei abrechnet.', null, 'ja', 'vollintegriert', '[]'::jsonb, true, 'Deutschland', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.datev.de/lohn', 'keins', 'DATEV eG', 1966, 'Nürnberg', '["Über die Steuerkanzlei","Telefon"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.4, 3.5, 4, 4.3, 4.9, 'DATEV Lohn und Gehalt ist der Maßstab für die Entgeltabrechnung in deutschen Steuerkanzleien. Kein anderes Programm bildet so viele Sonderfälle ab, dafür verlangt es Fachwissen und wird fast immer von der Kanzlei bedient.', '<h3>Einordnung</h3><p>Wenn Ihre Lohnabrechnung von der Steuerkanzlei erledigt wird, läuft sie mit hoher Wahrscheinlichkeit über DATEV. Lohn und Gehalt ist das Programm, mit dem Kanzleien und größere Lohnbüros monatlich abrechnen, Meldungen an Krankenkassen und Finanzamt übermitteln und Bescheinigungen erstellen.</p><h3>Stärken</h3><p>Die Abdeckung ist beeindruckend. Baulohn, Kurzarbeit, betriebliche Altersversorgung, Minijobs, Pfändungen und Sachbezüge sind abgebildet, und gesetzliche Änderungen kommen verlässlich zum Jahreswechsel. Wer einen komplizierten Personalbestand hat, ist hier am sichersten aufgehoben.</p><p>Über DATEV Unternehmen online können Sie Bewegungsdaten wie Stunden, Zuschläge oder Abwesenheiten selbst erfassen und Lohnunterlagen digital abrufen. Beschäftigte erhalten ihre Abrechnungen auf Wunsch über das Portal DATEV Arbeitnehmer online.</p><h3>Einschränkungen</h3><p>Für die eigenständige Nutzung im Betrieb ist das Programm wenig geeignet. Die Oberfläche ist auf Fachleute zugeschnitten, und die Lizenz läuft in der Regel über die Kanzlei. Wer die Lohnabrechnung selbst in der Hand haben möchte, ist mit Lexware lohn+gehalt oder Sage HR & Payroll besser bedient.</p><h3>Kosten</h3><p>Öffentliche Preise gibt es nicht. Die Kosten werden meist pro Abrechnung über die Kanzlei in Rechnung gestellt und sind Teil des Lohnbuchhaltungshonorars.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('DATEV LODAS', 'datev-lodas', 'Lohnabrechnung für komplexe Fälle und Lohnbüros', 'Die Lohnlösung von DATEV für große Mandantenzahlen, komplexe Abrechnungen und Lohnbüros.', '<p>DATEV LODAS ist auf eine hohe Zahl an Abrechnungen und komplexe Konstellationen ausgelegt, etwa bei Lohnbüros oder Kanzleien mit großem Lohnbereich. Die Abrechnung erfolgt im DATEV-Rechenzentrum.</p><p>Meldungen an Finanzamt und Sozialversicherung werden automatisch erzeugt und übermittelt.</p>', null, (select id from public.categories where slug = 'lohnabrechnung'), null, 'EUR', 'month', true, 'employee', false, null, false, true, '[]'::jsonb, 'Lizenz über die Steuerkanzlei', '["Entgeltabrechnung","ELStAM-Abruf","Lohnsteueranmeldung","DEÜV-Meldungen","Beitragsnachweise","Lohnsteuerbescheinigung","bAV & Entgeltumwandlung","Umlagen U1/U2/U3","DATEV-Schnittstelle","Baulohn"]'::jsonb, '["Rechenzentrumsverarbeitung","Massenabrechnung","Komplexe Sonderfälle"]'::jsonb, '["DATEV Unternehmen online","DATEV Kanzlei-Rechnungswesen"]'::jsonb, '["Skaliert auf viele Abrechnungen","Sehr rechtssicher"]'::jsonb, '["Nicht für Laien gedacht","Starre Bedienung"]'::jsonb, 'Lohnbüros und Kanzleien mit großem Lohnbereich.', null, 'ja', 'vollintegriert', '[]'::jsonb, true, 'Deutschland', true, true, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.datev.de/lodas', 'keins', 'DATEV eG', 1966, 'Nürnberg', '["Über die Steuerkanzlei","Telefon"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.2, 3.3, 4, 4.2, 4.7, 'LODAS ist die zweite Lohnlösung von DATEV und auf effiziente Massenabrechnung in Kanzleien ausgelegt. Für Unternehmen spielt der Unterschied zu Lohn und Gehalt kaum eine Rolle, entscheidend ist, womit Ihre Kanzlei arbeitet.', '<h3>Worin sich LODAS unterscheidet</h3><p>Während DATEV Lohn und Gehalt dialogorientiert arbeitet, ist LODAS auf Stapelverarbeitung ausgelegt. Daten werden erfasst und in einem Lauf abgerechnet. Das spart in Kanzleien mit vielen Mandanten Zeit, verlangt aber eine eingespielte Arbeitsweise.</p><h3>Für Unternehmen</h3><p>Als Mandant merken Sie von der Wahl zwischen LODAS und Lohn und Gehalt wenig. Sie liefern Bewegungsdaten über DATEV Unternehmen online oder per Vorerfassung, die Kanzlei rechnet ab, und die Unterlagen stehen digital bereit. Der Funktionsumfang bei Meldungen und Sonderfällen ist ähnlich umfassend.</p><h3>Kosten und Fazit</h3><p>Auch LODAS wird über die Kanzlei bereitgestellt und abgerechnet. Preise für Endkunden veröffentlicht DATEV nicht. Wenn Ihre Kanzlei LODAS nutzt, gibt es keinen Grund, daran etwas zu ändern.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Lexware lohn+gehalt', 'lexware-lohn-gehalt', 'Lohnabrechnung für die eigene Lohnbuchhaltung im KMU', 'Lohn- und Gehaltsabrechnung für kleine und mittlere Unternehmen mit ELStAM, DEÜV und Lohnsteueranmeldung.', '<p>Lexware lohn+gehalt ermöglicht kleinen und mittleren Unternehmen, die Lohnabrechnung selbst zu erledigen. Das Programm führt durch die monatliche Abrechnung und übermittelt Lohnsteueranmeldung, Beitragsnachweise und DEÜV-Meldungen elektronisch.</p><p>Buchungsdaten lassen sich an die Finanzbuchhaltung oder im DATEV-Format an die Kanzlei übergeben.</p>', null, (select id from public.categories where slug = 'lohnabrechnung'), 15, 'EUR', 'month', true, 'client', true, null, false, false, '[]'::jsonb, null, '["Entgeltabrechnung","ELStAM-Abruf","Lohnsteueranmeldung","DEÜV-Meldungen","Beitragsnachweise","Lohnsteuerbescheinigung","bAV & Entgeltumwandlung","Umlagen U1/U2/U3","DATEV-Schnittstelle"]'::jsonb, '["Geführte Monatsabrechnung","Elektronisches Meldewesen","DATEV-Übergabe"]'::jsonb, '["Lexware Office","DATEV","Lexware buchhaltung"]'::jsonb, '["Gut für Einsteiger in die eigene Lohnabrechnung","Solider Preis"]'::jsonb, '["Bei Sonderfällen schnell an Grenzen","Oberfläche nicht modern"]'::jsonb, 'KMU mit 1 bis 50 Mitarbeitenden, die den Lohn selbst abrechnen.', null, 'ja', 'export', '[]'::jsonb, true, 'on-premise', null, null, null, '[]'::jsonb, true, 'Deutschland', '2026-08-15', null, 'https://shop.lexware.de/lohn-gehalt', 'keins', 'Haufe-Lexware GmbH & Co. KG', 1989, 'Freiburg im Breisgau', '["E-Mail","Telefon","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.2, 4, 4.2, 4, 4.3, 'Lexware lohn+gehalt ist die bewährte Lösung für Betriebe, die ihre Lohnabrechnung selbst erledigen wollen. Wer bereits Lexware Office nutzt, sollte zuerst das dort integrierte Lohnmodul prüfen.', '<h3>Worum es geht</h3><p>Das Programm aus Freiburg ist seit Jahren eine der meistgenutzten Lohnlösungen für kleine und mittlere Betriebe, die nicht über die Kanzlei abrechnen. Es führt durch die monatliche Abrechnung, übermittelt Beitragsnachweise, DEÜV-Meldungen und Lohnsteueranmeldungen und erstellt die Lohnsteuerbescheinigungen.</p><h3>Stärken</h3><p>Die Abrechnung ist gut geführt, auch für Anwender ohne Lohnausbildung. Minijobs, Teilzeit, Zuschläge und die gängigen Sonderfälle sind abgedeckt. Für die Kanzlei gibt es einen Export im DATEV-Format, sodass die Buchungen aus der Lohnabrechnung ohne Abtippen in die Finanzbuchhaltung gelangen.</p><h3>Alternative im eigenen Haus</h3><p>Wer Lexware Office nutzt, kann dort ein Lohnmodul für 12,90 € im Monat hinzubuchen. Für wenige Beschäftigte mit einfachen Verhältnissen ist das oft die bequemere Wahl, weil Lohn und Buchhaltung in einem System bleiben. Bei vielen Sonderfällen spielt das eigenständige lohn+gehalt seine Stärken aus.</p><h3>Kosten</h3><p>Die Editionen werden im Lexware-Shop als Abonnement angeboten, der Preis hängt von der Edition und der Zahl der Abrechnungen ab. Prüfen Sie dort die aktuelle Staffel, bevor Sie sich festlegen.</p>', 'Nadeem Abbas', '2026-09-22', 'published', false),
('Sage HR & Payroll', 'sage-hr-payroll', 'Personalverwaltung und Lohnabrechnung in einer Cloud', 'Cloud-Lösung für HR und Lohnabrechnung mit gesetzlichen Meldungen, Self-Service für Mitarbeitende und Export an Sage und DATEV. Ab 40 € im Monat für fünf Mitarbeitende.', '<p>Sage HR & Payroll bringt Personalverwaltung und Entgeltabrechnung in eine gemeinsame Cloud-Anwendung. Stammdaten, Abwesenheiten und Dokumente pflegen Sie an einer Stelle, die Abrechnung greift direkt darauf zu. Meldungen an Finanzamt und Sozialversicherung erzeugt das System aus der laufenden Abrechnung.</p><p>Die Preislogik ist ungewöhnlich übersichtlich: Der Einstiegstarif Essentials kostet 40 € netto im Monat und deckt fünf Mitarbeitende ab, jede weitere Person kostet ab 7 €. Wer Sonderlöhne, mehrere Mandanten oder komplexere Abrechnungsfälle hat, landet im Tarif Standard für 60 €. Essentials lässt sich 30 Tage kostenlos testen, für alle Tarife gibt es eine Webdemo.</p>', null, (select id from public.categories where slug = 'lohnabrechnung'), 40, 'EUR', 'month', true, 'account', true, 30, false, true, '[{"name":"Essentials","price":40,"period":"month","unit":"account","features":["Cloud HR und Cloud Payroll","5 Mitarbeitende inklusive","weitere ab 7 € je Monat","Export an Sage und DATEV"]},{"name":"Standard","price":60,"period":"month","unit":"account","features":["Alles aus Essentials","Personalabrechnung für komplexere Fälle","Mehrmandantenfähig, Sonderlöhne","weitere Mitarbeitende ab 9 €"],"highlighted":true},{"name":"Premium","price":80,"period":"month","unit":"account","features":["Alles aus Standard","Umfassende HR-Prozesse"]}]'::jsonb, 'inkl. 5 Mitarbeitende, jeder weitere ab 7 €', '["Entgeltabrechnung","ELStAM-Abruf","Lohnsteueranmeldung","DEÜV-Meldungen","Beitragsnachweise","Lohnsteuerbescheinigung","Mitarbeiter-Self-Service","Onboarding-Portal","Abwesenheitsverwaltung","Export an Sage und DATEV"]'::jsonb, '["HR und Lohn in einer Oberfläche","Fester Preis für die ersten fünf Mitarbeitenden","Buchungsexport an Sage und DATEV","Self-Service-Portal für Beschäftigte"]'::jsonb, '["Sage Active","Sage 50","DATEV"]'::jsonb, '["Transparente Einstiegspreise","HR und Payroll ohne Schnittstellenbruch","30 Tage kostenlos testbar"]'::jsonb, '["Für Baulohn und sehr spezielle Branchenfälle weniger geeignet als DATEV","Größere Tarife nur mit Webdemo, nicht als Selbsttest"]'::jsonb, 'Kleine und mittlere Unternehmen, die HR und Lohn selbst in der Hand behalten wollen.', null, 'ja', 'export', '[]'::jsonb, true, 'EU', true, null, null, '[]'::jsonb, true, 'Deutschland', '2026-09-22', null, 'https://www.sage.com/de-de/produkte/sage-hr-payroll/', 'keins', 'Sage GmbH', null, 'Frankfurt am Main', '["Telefon","E-Mail","Hilfe-Center"]'::jsonb, '["Deutschland","Österreich","Schweiz"]'::jsonb, '["Deutsch"]'::jsonb, 4.3, 4.3, 4.4, 4.2, 4.2, 'Sage HR & Payroll ist eine der wenigen Cloud-Lösungen, die Personalverwaltung und Lohnabrechnung mit einem klaren Festpreis verbindet. Für kleine und mittlere Betriebe, die HR und Lohn selbst führen wollen, ist der Tarif Essentials für 40 € einer der fairsten Einstiege am Markt.', '<h3>Das Konzept</h3><p>Viele Betriebe arbeiten mit zwei Welten: einem HR-Tool für Urlaub, Dokumente und Stammdaten und einem getrennten Lohnprogramm oder der Kanzlei. Sage HR & Payroll führt beides zusammen. Wer einen neuen Mitarbeiter anlegt, legt ihn für HR und Abrechnung gleichzeitig an, Abwesenheiten fließen direkt in die Entgeltabrechnung.</p><h3>Was im Alltag hilft</h3><p>Beschäftigte pflegen ihre persönlichen Daten selbst im Self-Service, beantragen Urlaub und finden ihre Abrechnungen digital. Für neue Mitarbeitende gibt es ein Onboarding-Portal. Die gesetzlichen Meldungen an Finanzamt und Sozialversicherung erzeugt das System aus der laufenden Abrechnung.</p><p>Die Buchungssätze lassen sich an Sage und DATEV exportieren. Damit bleibt die Zusammenarbeit mit einer DATEV-Kanzlei möglich, auch wenn Sie die Abrechnung selbst machen.</p><h3>Preise</h3><p>Essentials kostet 40 € netto im Monat und enthält fünf Mitarbeitende, jede weitere Person kostet ab 7 €. Standard für 60 € ist für komplexere Abrechnungen gedacht, mit Sonderlöhnen, Mehrmandantenfähigkeit und einem Controlling-Modul, weitere Mitarbeitende kosten ab 9 €. Premium für 80 € deckt umfassende HR-Prozesse ab. Die Tarife sind jederzeit kündbar.</p><h3>Test und Fazit</h3><p>Essentials lässt sich 30 Tage kostenlos testen, für alle Tarife gibt es eine Webdemo. Für Firmen mit fünf bis fünfzig Beschäftigten ohne exotische Branchenregeln ist das Paket sehr stimmig. Baubetriebe mit Baulohn bleiben besser bei der Kanzlei und DATEV.</p>', 'Nadeem Abbas', '2026-09-22', 'published', true)
